{"code": "from collections import defaultdict
from itertools import combinations
import numpy as np
s=[r for r in load_lab() if r['family']=='spiral_classification' and not r.get('excluded')]; groups=defaultdict(list)
for r in s: groups[r['set_id']].append(r)
stats=defaultdict(list)
for rs in groups.values():
 for a,b in combinations(rs,2):
  if (a['optimizer']['type'],a['optimizer']['lr'])!=(b['optimizer']['type'],b['optimizer']['lr']):continue
  if b['depth']>a['depth']:a,b=b,a
  if a['depth']>=3 and a['n_ln']>=1 and not a['residual'] and b['depth']<=2 and b['n_ln']==0:
   delta=a['optimizer']['lr']*a['budget']['training_steps']; key=(a['dataset']['spiral_turns'], 'high' if delta>=.5 else 'low',b['residual'])
   stats[key].append((a['mean']<b['mean'],a['mean']/b['mean']))
for k,v in stats.items(): print(k,len(v),sum(x[0] for x in v),'ratio',round(float(np.median([x[1] for x in v])),3))
print('set sizes', {k:len(v) for k,v in list(groups.items())[:5]})"}
